// Turns what a module exports into the text of an unsafe/ wrapper. It reads types through the compiler it is given
// and writes nothing: the caller decides where the text goes.
import { err, type Mut, ok, type Result } from '@strict-ts/std';
import type ts from '@typescript/typescript6';

export interface Wrapper {
  /** The generated file. */
  readonly text: string;
  readonly wrapped: readonly string[];
  /** What was left out, and why: `name: reason`. */
  readonly skipped: readonly string[];
}

const IDENTIFIER = /^[A-Za-z_$][\w$]*$/;
const RESERVED = new Set(['default', 'delete', 'new', 'class', 'function', 'import', 'export', 'return', 'typeof', 'void', 'in', 'of']);

/**
 * Generates the wrapper of `module`, whose exports are `exported` as seen from `location`.
 *
 * Every function is wrapped the same way, since a declaration file does not say which ones throw: its call goes
 * through `attempt`, so an exception becomes an `Err`. A result of type `any` becomes `unknown`; a result that may
 * be null or undefined becomes an `Option`.
 */
export function generateWrapper(
  api: typeof ts,
  checker: ts.TypeChecker,
  module: string,
  exported: readonly ts.Symbol[],
  location: ts.Node,
): Result<Wrapper, string> {
  const wrapped: Mut<string[]> = [];
  const skipped: Mut<string[]> = [];
  const lines: Mut<string[]> = [];
  let needsPresent = false;

  const sorted = exported.toSorted((a, b) => (a.getName() < b.getName() ? -1 : 1));
  for (const symbol of sorted) {
    const name = symbol.getName();
    const target = (symbol.flags & api.SymbolFlags.Alias) !== 0 ? checker.getAliasedSymbol(symbol) : symbol;
    if ((target.flags & api.SymbolFlags.Value) === 0) continue;
    if (!IDENTIFIER.test(name) || RESERVED.has(name)) {
      skipped.push(`${name}: not a name a wrapper can take`);
      continue;
    }
    const type = checker.getTypeOfSymbolAtLocation(target, location);
    const signatures = type.getCallSignatures();
    if (type.getConstructSignatures().length > 0) {
      skipped.push(`${name}: a class; its constructor and methods are not wrapped`);
      continue;
    }
    if (signatures.length === 0) {
      const primitive =
        api.TypeFlags.StringLike | api.TypeFlags.NumberLike | api.TypeFlags.BooleanLike | api.TypeFlags.BigIntLike;
      const members = type.isUnion() ? type.types : [type];
      if (members.every((member) => (member.flags & primitive) !== 0)) {
        lines.push(`export const ${name} = lib.${name};`);
        wrapped.push(name);
      } else {
        skipped.push(`${name}: an object; its methods are not wrapped`);
      }
      continue;
    }

    const signature = signatures.at(-1);
    if (signature === undefined) continue;
    const returned = signature.getReturnType();
    const promise = returned.getSymbol()?.getName() === 'Promise';
    const value = promise ? (checker.getAwaitedType(returned) ?? returned) : returned;
    const any = (value.flags & api.TypeFlags.Any) !== 0;
    const absent = api.TypeFlags.Null | api.TypeFlags.Undefined;
    const nullable = value.isUnion() && value.types.some((member) => (member.flags & absent) !== 0);

    const notes = [
      ...(signatures.length > 1 ? [`${signatures.length} overloads: only the last one is wrapped`] : []),
      ...(signatures.some((s) => (s.typeParameters?.length ?? 0) > 0) ? ['generic: its type parameters are lost'] : []),
    ];
    const call = `lib.${name}(...args)`;
    const body = !any ? `() => ${call}` : promise ? `async (): Promise<unknown> => ${call}` : `(): unknown => ${call}`;
    const attempted = `attempt(${body}, threw('${name}'))`;
    const result = !nullable ? attempted : promise ? `${attempted}.then((result) => result.map(present))` : `${attempted}.map(present)`;
    needsPresent ||= nullable;
    for (const note of notes) lines.push(`// ${note}`);
    lines.push(`export const ${name} = (...args: Parameters<typeof lib.${name}>) => ${result};`);
    wrapped.push(name);
  }

  if (wrapped.length === 0) return err(`${module} exports nothing a wrapper can take`);

  const header = [
    `// Generated by @strict-ts/wrap from the declarations of "${module}". Do not edit: generate it again.`,
    '// Every function goes through `attempt`: its declarations do not say which ones throw, so all of them may.',
    ...(skipped.length === 0 ? [] : ['//', '// Not wrapped:', ...skipped.map((entry) => `//   ${entry}`)]),
    `import { attempt${needsPresent ? ', Option' : ''}, textOf } from '@strict-ts/std';`,
    `import * as lib from '${module}';`,
    '',
    '/** What a wrapped function threw, as a value. */',
    'export type Threw = { readonly kind: \'threw\'; readonly from: string; readonly message: string };',
    '',
    'const threw =',
    '  (name: string) =>',
    '  (cause: unknown): Threw => ({',
    "    kind: 'threw',",
    `    from: \`${module}.\${name}\`,`,
    '    message: textOf(cause),',
    '  });',
    ...(needsPresent
      ? ['', '/** null and undefined both become none. */', 'const present = <T>(value: T) => Option.from(value ?? undefined);']
      : []),
    '',
  ];
  return ok({ text: `${[...header, ...lines].join('\n')}\n`, wrapped, skipped });
}
